def convert_table(image, class_number, chapter):
    identity = f'{class_number}:{chapter}:' + image['filename'].split('_')[-1].split('.')[0]
    expected = {value[0]: digest for digest, value in TABLES.items()}
    if identity not in expected:
        return image
    if image['sha256'] != expected[identity]:
        raise ValueError('Reviewed table image changed: ' + identity)
    rows = TABLES[image['sha256']][1]
    widths = [.32, .68] if len(rows[0]) == 2 else [1 / len(rows[0])] * len(rows[0])
    return {'type': 'table', 'rows': rows, 'widths': widths,
            'merged_header': identity == '6:7:rId29', 'source_image': image,
            'source_identity': identity}
